import{_ as a,o as t,c as i,a6 as o}from"./chunks/framework.4tsfTCyC.js";const h=JSON.parse('{"title":"Best Practices","description":"","frontmatter":{},"headers":[],"relativePath":"guide/best-practices.md","filePath":"guide/best-practices.md"}'),s={name:"guide/best-practices.md"};function n(r,e,l,c,d,p){return t(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h1><h2 id="effective-prompting" tabindex="-1">Effective Prompting <a class="header-anchor" href="#effective-prompting" aria-label="Permalink to &quot;Effective Prompting&quot;">​</a></h2><p>Specific instructions reduce ambiguity - the model doesn&#39;t have to guess your intent and uses tokens more efficiently for your actual goal.</p><h3 id="be-specific" tabindex="-1">Be Specific <a class="header-anchor" href="#be-specific" aria-label="Permalink to &quot;Be Specific&quot;">​</a></h3><p>Instead of &quot;Make this better&quot;, try:</p><blockquote><p>Improve the clarity of the methodology section by simplifying complex sentences and adding transition phrases. Maintain all technical terminology.</p></blockquote><h3 id="define-boundaries" tabindex="-1">Define Boundaries <a class="header-anchor" href="#define-boundaries" aria-label="Permalink to &quot;Define Boundaries&quot;">​</a></h3><p>State what should and should not change:</p><blockquote><p>Enhance writing style in the introduction and discussion. Preserve all citations and mathematical expressions. Do not modify the results section.</p></blockquote><h3 id="provide-context" tabindex="-1">Provide Context <a class="header-anchor" href="#provide-context" aria-label="Permalink to &quot;Provide Context&quot;">​</a></h3><blockquote><p>Polish this abstract for submission to Nature Physics. Target audience: physicists with expertise in quantum field theory.</p></blockquote><h3 id="use-structured-instructions" tabindex="-1">Use Structured Instructions <a class="header-anchor" href="#use-structured-instructions" aria-label="Permalink to &quot;Use Structured Instructions&quot;">​</a></h3><p>For complex tasks:</p><blockquote><ol><li>Fix grammatical errors throughout</li><li>Make the introduction more engaging</li><li>Ensure consistent terminology</li><li>Improve transitions between sections</li></ol></blockquote><h2 id="model-selection" tabindex="-1">Model Selection <a class="header-anchor" href="#model-selection" aria-label="Permalink to &quot;Model Selection&quot;">​</a></h2><p>Match model capability to task complexity - overpowered models waste money, underpowered ones produce poor results.</p><ul><li><strong>Simple tasks</strong> (corrections): Use fast, cheap models (<code>gemini3f</code>, <code>gpt5-</code>, <code>haiku35</code>)</li><li><strong>Complex tasks</strong> (transformations): Use powerful models (<code>opus46</code>, <code>gpt52pro</code>)</li><li><strong>Reasoning-heavy</strong>: Use thinking models (<code>sonnet45T</code>, <code>opus46T</code>, <code>deepseekT</code>)</li></ul><p>See the <a href="./models.html">AI Models Guide</a> for detailed comparisons.</p><h2 id="file-management" tabindex="-1">File Management <a class="header-anchor" href="#file-management" aria-label="Permalink to &quot;File Management&quot;">​</a></h2><h3 id="project-structure" tabindex="-1">Project Structure <a class="header-anchor" href="#project-structure" aria-label="Permalink to &quot;Project Structure&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>project/</span></span>
<span class="line"><span>├── main.tex</span></span>
<span class="line"><span>├── chapters/</span></span>
<span class="line"><span>├── figures/</span></span>
<span class="line"><span>├── build/</span></span>
<span class="line"><span>├── history/</span></span>
<span class="line"><span>└── diffs/</span></span></code></pre></div><h3 id="best-practices-1" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices-1" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h3><ul><li>Include only necessary files in selections</li><li>Use the Pack button to preserve milestones</li><li>Clean unnecessary outputs regularly</li></ul><h2 id="workflow-integration" tabindex="-1">Workflow Integration <a class="header-anchor" href="#workflow-integration" aria-label="Permalink to &quot;Workflow Integration&quot;">​</a></h2><h3 id="staged-approach" tabindex="-1">Staged Approach <a class="header-anchor" href="#staged-approach" aria-label="Permalink to &quot;Staged Approach&quot;">​</a></h3><ol><li><strong>Research</strong>: <code>search</code> or <code>research</code> to find papers and verify ideas</li><li><strong>Writing</strong>: <code>chat</code> to draft LaTeX content interactively</li><li><strong>Development</strong>: <code>polish</code> for clarity and style</li><li><strong>Visualization</strong>: <code>draw</code> for figures, <code>presenter</code> for slides</li><li><strong>Finalization</strong>: <code>correct</code> for proofreading</li></ol><h3 id="quality-assurance" tabindex="-1">Quality Assurance <a class="header-anchor" href="#quality-assurance" aria-label="Permalink to &quot;Quality Assurance&quot;">​</a></h3><p>Always review AI-generated content:</p><ol><li>Compile to check for LaTeX errors</li><li>Verify cross-references and citations</li><li>Check figure and table numbering</li><li>Review mathematical expressions</li><li>Look for omissions or duplications</li></ol><p>Use <a href="./latex-diff.html">LaTeX Diff</a> to visualize changes between versions.</p><h2 id="latex-tips" tabindex="-1">LaTeX Tips <a class="header-anchor" href="#latex-tips" aria-label="Permalink to &quot;LaTeX Tips&quot;">​</a></h2><ul><li>Use logical document structure with proper sectioning</li><li>Maintain clean preambles</li><li>Use consistent label naming</li><li>Comment TikZ code for clarity</li><li>Use BibTeX consistently with a single bibliography file</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/guide/configuration.html">Configuration</a>: Customize TeXRA</li><li><a href="/guide/custom-agents.html">Custom Agents</a>: Create specialized agents</li><li><a href="/guide/intelligent-merge.html">Intelligent Merge</a>: Merge document versions</li></ul>`,34)])])}const m=a(s,[["render",n]]);export{h as __pageData,m as default};
